def load_service_key() -> str:
    env_key = os.environ.get("WELFARE_SERVICE_KEY")
    if env_key:
        return env_key.strip()
    return load_config().get("service_key", "")


def save_service_key(key: str):
    cfg = load_config()
    cfg["service_key"] = key.strip()
    save_config(cfg)


