        ttk.Button(pbtn_f, text="📝 최종원고(.md) 폴더 열기",
                   command=self._open_final_posts_folder).pack(side="left", padx=(0, 8), pady=6)
        # [v7.0 추가, 정책뉴스 TAB4 '제목 검색' 버튼에서 이식] 선택 항목의
