        # 고정 width를 새로 주지 않아도 전체 가로 사이즈(bs_folder_f는
        # sticky="ew"라 탭 폭에 맞춰짐, 탭 폭 자체는 다른 더 넓은 위젯
        # 들이 이미 결정해둔 값이라 이 행 때문에 창이 더 넓어지지 않음)
